 static ConnectionFactory Factory(){var factory=new ConnectionFactory(Cs);Func<SqlConnection,CancellationToken,Task> init=async(c,ct)=>{await using var cmd=c.CreateCommand();cmd.CommandText="EXECUTE AS USER=N'G02_Runtime'";await cmd.ExecuteNonQueryAsync(ct);};typeof(ConnectionFactory).GetProperty("SessionInitializer",BindingFlags.Instance|BindingFlags.NonPublic)!.SetValue(factory,init);return factory;}
